S.options = (d.options && String(d.options)) ? String(d.options).split("||") : [];
S.showQuiz = (d.showQuiz === true && (d.phase === "quiz" || S.phase.toLowerCase().indexOf("quiz") >= 0));
S.showResult = d.showResult === true;
S.scoreLabel = d.scoreLabel || "";
S.selectedAnswer = parseInt(d.selectedAnswer, 10);
if (isNaN(S.selectedAnswer)) S.selectedAnswer = -1;
S.waitingForUser = d.waitingForUser === true;
S.isPlayingAudio = d.isPlayingAudio === true;
S.modelPartCount = parseInt(d.modelPartCount, 10) || 0;
S.currentMcqIndex = parseInt(d.currentMcqIndex, 10) || 0;
S.totalMcqs = parseInt(d.totalMcqs, 10) || 0;
S.correctAnswer = parseInt(d.correctAnswer, 10);
if (isNaN(S.correctAnswer)) S.correctAnswer = -1;
S.explanation = d.explanation || "";
S.controlStudentsEnabled = d.controlStudentsEnabled === true;
S.isStudent = d.isStudent === true;
S.isHost = d.isHost === true;

if (refs.panel.draw) refs.panel.draw();

if (refs.startAnim) refs.startAnim();

// Trigger ambient light pulse on phase change
if (window.__ambienceLightPulse) window.__ambienceLightPulse();

var refs = krpano.immersive_ui_refs;
if (!refs || !refs.panel || !refs.panel.mesh) return;
var THREE = krpano.threejs.THREE;
if (!THREE) return;

var CW = 2048, CH = 1280;
var panelMesh = refs.panel.mesh;
var camera = krpano.threejs.camera;
if (!camera) return;

var raycaster = new THREE.Raycaster();
var ndc = new THREE.Vector2(
  (krpano.mouse.x / krpano.stagewidth) * 2 - 1,
  -(krpano.mouse.y / krpano.stageheight) * 2 + 1
);
raycaster.setFromCamera(ndc, camera);
var hits = raycaster.intersectObject(panelMesh);
if (hits.length > 0 && hits[0].uv) {
  var u = hits[0].uv.x;
  var v = 1 - hits[0].uv.y;
  var cx = u * CW;
  var cy = v * CH;

  var regions = refs.buttonRegions || [];
  var pad = 4;
  for (var i = 0; i < regions.length; i++) {
    var r = regions[i];
    if (cx >= r.x - pad && cx <= r.x + r.w + pad && cy >= r.y - pad && cy <= r.y + r.h + pad) {
      var act = r.action;
      if (act && act.indexOf("layoutToggle:") === 0) {
        var lname = act.split(":")[1];
        window.__krpanoLayoutToSet = lname;
        krpano.call("immersive_ui_set_layout()");
        if (window.__xrHaptic) window.__xrHaptic("layout");
      } else if (act && act.indexOf("phaseGo:") === 0) {
        if (window.__krpanoUIAction) window.__krpanoUIAction(act);
        if (window.__xrHaptic) window.__xrHaptic("layout");
      } else if (window.__krpanoUIAction) {
        window.__krpanoUIAction(act);
        if (window.__xrHaptic) {
          var htype = act === "mcqSubmit" ? "confirm" : act === "continue" ? "select" : "select";
          window.__xrHaptic(htype);
        }
      }
      break;
    }
  }
}

var refs = krpano.immersive_ui_refs;
if (!refs || !refs.layouts) return;
var layoutName = (window.__krpanoLayoutToSet || "lecture");
var layout = refs.layouts[layoutName];
if (!layout) return;
refs.currentLayout = layoutName;
refs.gazeSignature = "";
refs.hoverAction = null;

var TWEEN_SPEED = 0.6;
var TWEEN_TYPE = "easeInOutQuad";

// Smooth tween for panel
var p = layout.panel;
krpano.call("tween(hotspot[iu_panel_3d].tx," + p.tx + "," + TWEEN_SPEED + "," + TWEEN_TYPE + ")");
krpano.call("tween(hotspot[iu_panel_3d].ty," + p.ty + "," + TWEEN_SPEED + "," + TWEEN_TYPE + ")");
krpano.call("tween(hotspot[iu_panel_3d].tz," + p.tz + "," + TWEEN_SPEED + "," + TWEEN_TYPE + ")");

// Smooth tween for avatar
try {
  var a = layout.avatar;
  krpano.call("tween(hotspot[teacher_avatar].tx," + a.tx + "," + TWEEN_SPEED + "," + TWEEN_TYPE + ")");
  krpano.call("tween(hotspot[teacher_avatar].ty," + a.ty + "," + TWEEN_SPEED + "," + TWEEN_TYPE + ")");
  krpano.call("tween(hotspot[teacher_avatar].tz," + a.tz + "," + TWEEN_SPEED + "," + TWEEN_TYPE + ")");
} catch(e) {}

// Smooth tween for assets
var ab = layout.asset;
var sp = layout.spread;
for (var i = 0; i < 10; i++) {
  var hsName = "asset_" + i;
  try {
    var hs = krpano.get("hotspot[" + hsName + "]");
    if (hs) {
      var atx = ab.tx + (i % 3 - 1) * sp.x;
      var aty = ab.ty;
      var atz = ab.tz + Math.floor(i / 3) * sp.z;
      krpano.call("tween(hotspot[" + hsName + "].tx," + atx + "," + TWEEN_SPEED + "," + TWEEN_TYPE + ")");
      krpano.call("tween(hotspot[" + hsName + "].ty," + aty + "," + TWEEN_SPEED + "," + TWEEN_TYPE + ")");
      krpano.call("tween(hotspot[" + hsName + "].tz," + atz + "," + TWEEN_SPEED + "," + TWEEN_TYPE + ")");
    }
  } catch(e) { break; }
}

if (refs.panel && refs.panel.draw) refs.panel.draw();
krpano.call("immersive_ui_gaze_update_positions()");
try {
  if (window.__krpanoAssetScaleAction) window.__krpanoAssetScaleAction("refresh");
} catch(e) {}

var refs = krpano.immersive_ui_refs;
if (!refs || !refs.panel || !refs.panel.mesh) return;
var t = window.__krpanoPanelTransform;
if (!t) return;

var hs = null;
try { hs = krpano.get("hotspot[iu_panel_3d]"); } catch (e) { hs = null; }
if (hs) {
	if (isFinite(t.tx)) krpano.set("hotspot[iu_panel_3d].tx", t.tx);
	if (isFinite(t.ty)) krpano.set("hotspot[iu_panel_3d].ty", t.ty);
	if (isFinite(t.tz)) krpano.set("hotspot[iu_panel_3d].tz", t.tz);
}
if (isFinite(t.scale) && t.scale > 0) {
	refs.panel.mesh.scale.set(-t.scale, t.scale, t.scale);
}
// Gaze-button proxies are positioned off the panel, so re-place them after a move.
if (typeof krpano.call === "function") krpano.call("immersive_ui_gaze_update_positions()");

if (window.__krpanoPanelDragInstalled) return;
window.__krpanoPanelDragInstalled = true;

var num = function (name) {
	var v = Number(krpano.get(name));
	return isFinite(v) ? v : 0;
};
var panelScale = function () {
	var refs = krpano.immersive_ui_refs;
	return (refs && refs.panel && refs.panel.mesh) ? Math.abs(refs.panel.mesh.scale.y) || 1 : 1;
};

var session = null;
var raf = null;

var handleName = function (mode) {
	// The proxies are named by their index in refs.buttonRegions, so find ours by the
	// dataaction we stamped on it rather than assuming a fixed index.
	var refs = krpano.immersive_ui_refs;
	if (!refs || !refs.gazeHotspotNames) return null;
	var wanted = mode === "grab" ? "panelGrab" : "panelResize";
	for (var i = 0; i < refs.gazeHotspotNames.length; i++) {
		var n = refs.gazeHotspotNames[i];
		if (String(krpano.get("hotspot[" + n + "].dataaction")) === wanted) return n;
	}
	return null;
};

var stop = function () {
	if (raf !== null) { cancelAnimationFrame(raf); raf = null; }
	session = null;
	krpano.immersive_ui_panel_dragging = false;
};

var tick = function () {
	if (!session) return;
	var hn = session.handle;
	var hx = num("hotspot[" + hn + "].tx");
	var hy = num("hotspot[" + hn + "].ty");
	var hz = num("hotspot[" + hn + "].tz");

	if (session.mode === "grab") {
		krpano.set("hotspot[iu_panel_3d].tx", session.panel.tx + (hx - session.handle0.tx));
		krpano.set("hotspot[iu_panel_3d].ty", session.panel.ty + (hy - session.handle0.ty));
		krpano.set("hotspot[iu_panel_3d].tz", session.panel.tz + (hz - session.handle0.tz));
	} else {
		// Scale from how much further the corner was pulled from the panel centre.
		var dx = hx - session.panel.tx, dy = hy - session.panel.ty;
		var dist = Math.sqrt(dx * dx + dy * dy);
		if (session.dist0 > 0.0001) {
			var next = Math.max(0.4, Math.min(2.5, session.scale0 * (dist / session.dist0)));
			var refs = krpano.immersive_ui_refs;
			if (refs && refs.panel && refs.panel.mesh) refs.panel.mesh.scale.set(-next, next, next);
		}
	}
	raf = requestAnimationFrame(tick);
};

var start = function (mode) {
	var hn = handleName(mode);
	if (!hn) return;
	stop();
	var px = num("hotspot[iu_panel_3d].tx");
	var py = num("hotspot[iu_panel_3d].ty");
	var pz = num("hotspot[iu_panel_3d].tz");
	var hx = num("hotspot[" + hn + "].tx");
	var hy = num("hotspot[" + hn + "].ty");
	var hz = num("hotspot[" + hn + "].tz");
	var ddx = hx - px, ddy = hy - py;
	session = {
		mode: mode, handle: hn,
		panel: { tx: px, ty: py, tz: pz },
		handle0: { tx: hx, ty: hy, tz: hz },
		dist0: Math.sqrt(ddx * ddx + ddy * ddy),
		scale0: panelScale()
	};
	krpano.immersive_ui_panel_dragging = true;
	raf = requestAnimationFrame(tick);
};

window.__krpanoPanelGrabStart = function () { start("grab"); };
window.__krpanoPanelResizeStart = function () { start("resize"); };
window.__krpanoPanelDragEnd = function () {
	stop();
	// Persist, then re-place the proxies onto the panel's new position/size.
	krpano.call("immersive_ui_report_panel_transform()");
	krpano.call("immersive_ui_gaze_update_positions()");
};

var refs = krpano.immersive_ui_refs;
var m = (refs && refs.panel && refs.panel.mesh) ? Math.abs(refs.panel.mesh.scale.y) : 1;
window.__krpanoPanelTransform = {
	tx: Number(krpano.get("hotspot[iu_panel_3d].tx")) || 0,
	ty: Number(krpano.get("hotspot[iu_panel_3d].ty")) || 0,
	tz: Number(krpano.get("hotspot[iu_panel_3d].tz")) || 0,
	scale: isFinite(m) && m > 0 ? m : 1
};
if (window.__krpanoOnPanelTransform) window.__krpanoOnPanelTransform(window.__krpanoPanelTransform);
